// FLUX-1739: `raiseNeedsAction` writes the needsAction FLAG for a benchmark run but emits NO user
// notification.
//
// The distinction matters and is easy to get backwards. A benchmark run PARKING is not a problem to
// escalate — it is a measurement: the friction layer reads that flag off frontmatter as a
// protocol-violation signal, and the whole point of the L2.5 layer is to count how often runs park.
// But a 45-cell suite firing 45 "needs action" notifications would bury the user's real board
// alerts under noise generated by the benchmark doing exactly what it was built to do.
//
// So: the flag is DATA (keep it), the notification is NOISE (suppress it).
import { describe, it, expect, vi, beforeEach } from 'vitest';

const generateNeedsActionNotification = vi.fn();
const updateTaskWithHistory = vi.fn(async () => {});
const broadcastEvent = vi.fn();
const tasks: Record<string, Record<string, unknown>> = {};

vi.mock('./notifications.js', () => ({ generateNeedsActionNotification }));
vi.mock('./task-store.js', () => ({ updateTaskWithHistory }));
vi.mock('./events.js', () => ({ broadcastEvent }));
vi.mock('./workspace-context.js', () => ({ getWorkspace: () => ({ tasks }) }));
vi.mock('./config.js', () => ({ getConfig: () => ({}) }));

const { raiseNeedsAction } = await import('./parked-ticket.js');

function seed(id: string, extra: Record<string, unknown> = {}) {
  tasks[id] = { id, title: `t ${id}`, status: 'In Progress', ...extra };
}

beforeEach(() => {
  generateNeedsActionNotification.mockClear();
  updateTaskWithHistory.mockClear();
  for (const k of Object.keys(tasks)) delete tasks[k];
});

describe('raiseNeedsAction on a benchmark run ticket', () => {
  it('writes the needsAction flag — the friction layer reads it as evidence', async () => {
    seed('BENCH-1', { kind: 'benchmark' });
    await raiseNeedsAction('BENCH-1', 'parked without a board action');

    expect(updateTaskWithHistory).toHaveBeenCalledTimes(1);
    const [id, payload] = updateTaskWithHistory.mock.calls[0] as unknown as [string, { extraFields: Record<string, unknown> }];
    expect(id).toBe('BENCH-1');
    expect(payload.extraFields).toEqual({ needsAction: 'parked without a board action' });
  });

  it('emits NO user notification', async () => {
    seed('BENCH-2', { kind: 'benchmark' });
    await raiseNeedsAction('BENCH-2', 'parked without a board action');
    expect(generateNeedsActionNotification).not.toHaveBeenCalled();
  });

  it('still notifies for an ordinary ticket — the suppression is scoped to kind', async () => {
    seed('FLUX-1', {});
    await raiseNeedsAction('FLUX-1', 'parked without a board action');
    expect(generateNeedsActionNotification).toHaveBeenCalledTimes(1);
  });

  it('still notifies for a scratch ticket — only benchmark is suppressed', async () => {
    seed('SCRATCH-1', { kind: 'scratch' });
    await raiseNeedsAction('SCRATCH-1', 'parked without a board action');
    expect(generateNeedsActionNotification).toHaveBeenCalledTimes(1);
  });

  it('does not re-write the flag when one already stands, but still suppresses the notification', async () => {
    seed('BENCH-3', { kind: 'benchmark', needsAction: 'already set' });
    await raiseNeedsAction('BENCH-3', 'parked again');
    expect(updateTaskWithHistory).not.toHaveBeenCalled();
    expect(generateNeedsActionNotification).not.toHaveBeenCalled();
  });
});
